files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #f0f4f8;
  --card-bg: #ffffff;
  --text: #1e293b;
  --muted: #64748b;
  --accent: #2a9d8f;
  --accent-hover: #21867a;
  --border: #cbd5e1;
  --cell-empty: #f8fafc;
  --cell-border: #e2e8f0;
  --focus-ring: #2a9d8f;
  --shadow: 0 4px 24px rgba(0, 0, 0, 0.08);
  --radius: 12px;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 600px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  color: var(--text);
}

.subtitle {
  text-align: center;
  color: var(--muted);
  font-size: 0.95rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 2px;
  background: var(--cell-border);
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 2px;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  user-select: none;
}

.cell {
  background: var(--cell-empty);
  border: none;
  border-radius: 2px;
  cursor: pointer;
  aspect-ratio: 1 / 1;
  min-width: 0;
  min-height: 0;
  padding: 0;
  transition: background 0.1s, transform 0.05s;
}

.cell:hover {
  filter: brightness(0.92);
}

.cell:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
  z-index: 1;
  position: relative;
}

.cell:active {
  transform: scale(0.9);
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.swatch {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 3px solid transparent;
  background: var(--swatch);
  cursor: pointer;
  transition: transform 0.1s, border-color 0.1s, box-shadow 0.1s;
  padding: 0;
}

.swatch:hover {
  transform: scale(1.1);
}

.swatch:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.swatch:active {
  transform: scale(0.95);
}

.swatch.selected {
  border-color: var(--text);
  box-shadow: 0 0 0 2px var(--card-bg), 0 0 0 4px var(--text);
}

.actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 24px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: var(--card-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.btn:hover {
  background: #f1f5f9;
  border-color: var(--muted);
}

.btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn-eraser[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn-clear:hover {
  background: #fee2e2;
  border-color: #ef4444;
  color: #b91c1c;
}

.count {
  text-align: center;
  font-weight: 600;
  color: var(--muted);
  font-size: 1rem;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    gap: 14px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .swatch {
    width: 36px;
    height: 36px;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.95rem;
  }
  .grid {
    gap: 1px;
    padding: 1px;
  }
}

(function () {
  'use strict';

  const GRID_SIZE = 16;
  const gridEl = document.getElementById('grid');
  const paletteEl = document.getElementById('palette');
  const eraserBtn = document.getElementById('eraser');
  const clearBtn = document.getElementById('clear');
  const countEl = document.getElementById('count');

  let selectedColor = '#e63946';
  let eraserActive = false;

  // Build grid
  const cells = [];
  for (let i = 0; i < GRID_SIZE * GRID_SIZE; i++) {
    const cell = document.createElement('button');
    cell.className = 'cell';
    cell.type = 'button';
    cell.setAttribute('role', 'gridcell');
    cell.setAttribute('aria-label', `Cell ${Math.floor(i / GRID_SIZE) + 1}, ${(i % GRID_SIZE) + 1}`);
    cell.dataset.painted = 'false';
    cell.addEventListener('click', () => paintCell(cell));
    gridEl.appendChild(cell);
    cells.push(cell);
  }

  function paintCell(cell) {
    if (eraserActive) {
      cell.style.background = '';
      cell.dataset.painted = 'false';
    } else {
      cell.style.background = selectedColor;
      cell.dataset.painted = 'true';
    }
    updateCount();
  }

  function updateCount() {
    const painted = cells.filter(c => c.dataset.painted === 'true').length;
    countEl.textContent = `Painted cells: ${painted}`;
  }

  // Palette selection
  const swatches = paletteEl.querySelectorAll('.swatch');
  swatches.forEach(swatch => {
    swatch.addEventListener('click', () => {
      selectedColor = swatch.dataset.color;
      eraserActive = false;
      eraserBtn.setAttribute('aria-pressed', 'false');
      swatches.forEach(s => s.classList.remove('selected'));
      swatch.classList.add('selected');
    });
  });

  // Default selection
  swatches[0].classList.add('selected');

  // Eraser toggle
  eraserBtn.addEventListener('click', () => {
    eraserActive = !eraserActive;
    eraserBtn.setAttribute('aria-pressed', String(eraserActive));
    if (eraserActive) {
      swatches.forEach(s => s.classList.remove('selected'));
    } else {
      const current = paletteEl.querySelector(`[data-color="${selectedColor}"]`);
      if (current) current.classList.add('selected');
    }
  });

  // Clear all
  clearBtn.addEventListener('click', () => {
    cells.forEach(cell => {
      cell.style.background = '';
      cell.dataset.painted = 'false';
    });
    updateCount();
  });

  updateCount();
})();
